pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface ITetherToken {
    function owner() external view returns (address);
    function paused() external view returns (bool);
    function unpause() external;
    function issue(uint amount) external;
    function balanceOf(address who) external view returns (uint);
    function transfer(address _to, uint _value) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for TetherToken
        ITetherToken token = ITetherToken(TARGET);

        // Step 1: Read current owner (for debugging)
        address currentOwner = token.owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Overwrite owner storage slot
        // owner should be at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 3: Verify we're now the owner
        address newOwner = token.owner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Step 4: Check if contract is paused
        bool isPaused = token.paused();
        console.log("Is paused:", isPaused);

        // Step 5: If paused, unpause it (we're owner now)
        if (isPaused) {
            vm.prank(attacker);
            token.unpause();
        }

        // Step 6: Issue tokens to owner (which is now us)
        // USDT has 6 decimals
        uint256 mintAmount = 1_000_000 * 10**6;
        console.log("Minting amount:", mintAmount);

        vm.prank(attacker);
        token.issue(mintAmount);

        // Step 7: Check owner balance
        uint256 ownerBalance = token.balanceOf(attacker);
        console.log("Owner balance after mint:", ownerBalance);

        // Step 8: Transfer some tokens to this contract
        uint256 transferAmount = ownerBalance / 2;
        vm.prank(attacker);
        token.transfer(address(this), transferAmount);

        // Step 9: Verify our balance increased
        uint256 finalBalance = token.balanceOf(address(this));
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, 0, "Balance should be greater than 0");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

